90: CREATE TABLE dbo.m_code_category (
91:   category_id varchar(24) COLLATE Latin1_General_100_BIN2 NOT NULL,
92:   category_name nvarchar(24) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
93:   code_length smallint NOT NULL,
94:   allow_add bit NOT NULL,
95:   is_active bit NOT NULL CONSTRAINT df_m_code_category_is_active DEFAULT (1),
96:   remarks nvarchar(240) COLLATE Latin1_General_100_CS_AS_SC NULL,
97:   created_at datetimeoffset(7) NOT NULL,
98:   created_by nvarchar(128) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
99:   updated_at datetimeoffset(7) NOT NULL,
100:   updated_by nvarchar(128) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
101:   row_version bigint NOT NULL CONSTRAINT df_m_code_category_row_version DEFAULT (1),
102:   CONSTRAINT pk_m_code_category PRIMARY KEY (category_id),
103:   CONSTRAINT ck_m_code_category_category_name_scalar CHECK (category_name IS NULL OR LEN(CONVERT(nvarchar(max),category_name) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=12),
104:   CONSTRAINT ck_m_code_category_remarks_scalar CHECK (remarks IS NULL OR LEN(CONVERT(nvarchar(max),remarks) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=120),
105:   CONSTRAINT ck_m_code_category_created_at_utc CHECK (created_at IS NULL OR DATEPART(TZOFFSET,created_at)=0),
106:   CONSTRAINT ck_m_code_category_created_by_scalar CHECK (created_by IS NULL OR LEN(CONVERT(nvarchar(max),created_by) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=64),
107:   CONSTRAINT ck_m_code_category_updated_at_utc CHECK (updated_at IS NULL OR DATEPART(TZOFFSET,updated_at)=0),
108:   CONSTRAINT ck_m_code_category_updated_by_scalar CHECK (updated_by IS NULL OR LEN(CONVERT(nvarchar(max),updated_by) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=64),
109:   CONSTRAINT ck_m_code_category_row_version CHECK (row_version>0)
110: );
111: GO
112: CREATE TABLE dbo.m_code (
113:   category_id varchar(24) COLLATE Latin1_General_100_BIN2 NOT NULL,
114:   code_value varchar(10) COLLATE Latin1_General_100_BIN2 NOT NULL,
115:   code_name nvarchar(24) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
116:   display_order int NOT NULL CONSTRAINT df_m_code_display_order DEFAULT (0),
117:   is_active bit NOT NULL CONSTRAINT df_m_code_is_active DEFAULT (1),
118:   valid_from date NOT NULL,
119:   valid_to date NULL,
120:   is_protected bit NOT NULL,
121:   remarks nvarchar(240) COLLATE Latin1_General_100_CS_AS_SC NULL,
122:   created_at datetimeoffset(7) NOT NULL,
123:   created_by nvarchar(128) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
124:   updated_at datetimeoffset(7) NOT NULL,
125:   updated_by nvarchar(128) COLLATE Latin1_General_100_CS_AS_SC NOT NULL,
126:   row_version bigint NOT NULL CONSTRAINT df_m_code_row_version DEFAULT (1),
127:   CONSTRAINT pk_m_code PRIMARY KEY (category_id,code_value),
128:   CONSTRAINT ck_m_code_code_name_scalar CHECK (code_name IS NULL OR LEN(CONVERT(nvarchar(max),code_name) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=12),
129:   CONSTRAINT ck_m_code_remarks_scalar CHECK (remarks IS NULL OR LEN(CONVERT(nvarchar(max),remarks) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=120),
130:   CONSTRAINT ck_m_code_created_at_utc CHECK (created_at IS NULL OR DATEPART(TZOFFSET,created_at)=0),
131:   CONSTRAINT ck_m_code_created_by_scalar CHECK (created_by IS NULL OR LEN(CONVERT(nvarchar(max),created_by) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=64),
132:   CONSTRAINT ck_m_code_updated_at_utc CHECK (updated_at IS NULL OR DATEPART(TZOFFSET,updated_at)=0),
133:   CONSTRAINT ck_m_code_updated_by_scalar CHECK (updated_by IS NULL OR LEN(CONVERT(nvarchar(max),updated_by) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=64),
134:   CONSTRAINT ck_m_code_row_version CHECK (row_version>0)
